 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Repeated diagonal color segments are extended backward toward the top
    # border, as in the demonstrations. Keep all original cells intact.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                streak = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    streak.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(streak) < 2:
                    continue
                # Continue the segment in the direction toward the top edge.
                rr, cc = r - dr, c - dc
                while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                    out[rr][cc] = color
                    rr -= dr
                    cc -= dc
    return out
