    # color upward (toward decreasing row indices) to the grid boundary.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dc in (-1, 1):
                # Require this cell to be the upper end of a downward-running
                # segment so each diagonal is handled once.
                rr, cc = r + 1, c + dc
                if not (0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color):
                    continue
                # Trace the full matching run, then extend it only toward top.
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    rr += 1
                    cc += dc
                rr, cc = r - 1, c - dc
                while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                    out[rr][cc] = color
                    rr -= 1
                    cc -= dc
    return out
