 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    out = [row[:] for row in grid]
    # Extend a diagonal line of color whenever at least two neighboring
    # cells on that diagonal establish its direction; project toward the
    # nearest/topward border while preserving all existing colored cells.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color:
                    # cells in the same diagonal pattern, extend backward
                    rr, cc = r - dr, c - dc
                    while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                        out[rr][cc] = color
                        rr -= dr
                        cc -= dc
    return out
