                    n += 1
                    rr += dr
                    cc += dc
                if n >= 2:
                    rr, cc = r - dr, c - dc
                    while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                        out[rr][cc] = color
                        rr -= dr
                        cc -= dc
    return out
