 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    out = [row[:] for row in grid]
    # Extend matching diagonal segments to the boundary in both directions.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                pr, pc = r-dr, c-dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                cells=[]
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    cells.append((rr,cc)); rr+=dr; cc+=dc
                if len(cells) < 2:
                    continue
                for rr,cc,sr,sc in ((r-dr,c-dc,-dr,-dc),(cells[-1][0]+dr,cells[-1][1]+dc,dr,dc)):
                    while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                        out[rr][cc]=color; rr+=sr; cc+=sc
    return out
